metadata.er-schema:
{
  "title": "looply · Market 市场主数据实体关系图",
  "version": "v4.0 · 2026-04-29",
  "tables": [
    {
      "name": "country",
      "comment": "国家/地区",
      "columns": [
        {
          "name": "country_code",
          "comment": "国家代码（如US/FR/DE）",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "country_name",
          "comment": "国家名称（英文）",
          "constraint": ""
        },
        {
          "name": "country_name_local",
          "comment": "本地语言名称",
          "constraint": ""
        },
        {
          "name": "continent",
          "comment": "所属大洲",
          "constraint": ""
        },
        {
          "name": "is_multi_timezone",
          "comment": "是否多时区国家",
          "constraint": ""
        },
        {
          "name": "dial_code",
          "comment": "电话区号（如+1/+33）",
          "constraint": ""
        },
        {
          "name": "default_currency_code",
          "comment": "法定货币",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "default_language_code",
          "comment": "主要语言",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "status",
          "comment": "状态",
          "constraint": ""
        }
      ],
      "note": "ISO 3166-1 alpha-2 作主键，全局唯一，多模块共用"
    },
    {
      "name": "currency",
      "comment": "货币",
      "columns": [
        {
          "name": "currency_code",
          "comment": "货币代码（如USD/EUR/GBP）",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "currency_name",
          "comment": "货币名称（英文）",
          "constraint": ""
        },
        {
          "name": "currency_symbol",
          "comment": "符号（如$/€/£）",
          "constraint": ""
        },
        {
          "name": "decimal_places",
          "comment": "小数位数",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态",
          "constraint": ""
        }
      ],
      "note": "ISO 4217 作主键，decimal_places 影响价格计算（JPY=0, USD=2, KWD=3）"
    },
    {
      "name": "language",
      "comment": "语言",
      "columns": [
        {
          "name": "language_code",
          "comment": "语言代码（如en/fr/de）",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "language_name",
          "comment": "语言名称（英文）",
          "constraint": ""
        },
        {
          "name": "language_name_local",
          "comment": "本地语言名称",
          "constraint": ""
        },
        {
          "name": "rtl",
          "comment": "是否从右到左",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态",
          "constraint": ""
        }
      ],
      "note": "ISO 639-1 作主键，rtl 影响前端布局方向（阿拉伯语/希伯来语）"
    },
    {
      "name": "timezone",
      "comment": "时区",
      "columns": [
        {
          "name": "timezone_id",
          "comment": "时区ID（IANA标识，如America/New_York）",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "timezone_name",
          "comment": "时区名称（如Eastern Time）",
          "constraint": ""
        },
        {
          "name": "utc_offset",
          "comment": "UTC偏移（如UTC-5）",
          "constraint": ""
        },
        {
          "name": "has_dst",
          "comment": "是否有夏令时",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态",
          "constraint": ""
        }
      ],
      "note": "IANA 时区数据库标识，系统自动同步维护，不支持手动新增"
    },
    {
      "name": "country_timezone",
      "comment": "国家-时区关联",
      "columns": [
        {
          "name": "id",
          "comment": "关联ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "country_code",
          "comment": "国家代码",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "timezone_id",
          "comment": "时区ID",
          "constraint": "FOREIGN KEY"
        }
      ],
      "note": "一个国家可对应多个时区（如US有4个），单时区国家也保留1条记录"
    },
    {
      "name": "market",
      "comment": "Market 市场",
      "columns": [
        {
          "name": "market_id",
          "comment": "Market ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "market_code",
          "comment": "Market 代码（如US/EU/APAC）",
          "constraint": "UNIQUE"
        },
        {
          "name": "market_name",
          "comment": "Market 名称",
          "constraint": ""
        },
        {
          "name": "base_timezone",
          "comment": "基准时区",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "business_day_cutoff",
          "comment": "业务日切时间",
          "constraint": ""
        },
        {
          "name": "launch_date",
          "comment": "上线日期",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态（planning/active/suspended）",
          "constraint": ""
        }
      ],
      "note": "Market = 商业运营单元，一个 Market 可包含多个国家"
    },
    {
      "name": "market_country",
      "comment": "Market-国家关联",
      "columns": [
        {
          "name": "id",
          "comment": "关联ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "market_id",
          "comment": "Market ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "country_code",
          "comment": "国家代码",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "is_primary",
          "comment": "是否主要国家",
          "constraint": ""
        },
        {
          "name": "priority",
          "comment": "优先级",
          "constraint": ""
        },
        {
          "name": "use_independent_domain",
          "comment": "是否使用独立域名",
          "constraint": ""
        },
        {
          "name": "independent_domain",
          "comment": "独立域名（如looply.fr）",
          "constraint": ""
        },
        {
          "name": "local_timezone",
          "comment": "本地时区（可选覆盖）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "local_day_cutoff",
          "comment": "本地日切时间（可选覆盖）",
          "constraint": ""
        },
        {
          "name": "custom_config",
          "comment": "例外配置（JSON）",
          "constraint": ""
        },
        {
          "name": "launch_date",
          "comment": "该国上线日期",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态（active/suspended）",
          "constraint": ""
        }
      ],
      "note": "一个 Market 包含多个国家，支持国家级独立域名配置"
    },
    {
      "name": "market_language",
      "comment": "Market-语言关联",
      "columns": [
        {
          "name": "id",
          "comment": "关联ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "market_id",
          "comment": "Market ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "language_code",
          "comment": "语言代码",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "is_default",
          "comment": "是否默认语言",
          "constraint": ""
        },
        {
          "name": "priority",
          "comment": "优先级",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态",
          "constraint": ""
        }
      ],
      "note": "一个 Market 支持多种语言，is_default 标记默认语言"
    },
    {
      "name": "market_currency",
      "comment": "Market-货币关联",
      "columns": [
        {
          "name": "id",
          "comment": "关联ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "market_id",
          "comment": "Market ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "currency_code",
          "comment": "货币代码",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "is_default",
          "comment": "是否默认货币",
          "constraint": ""
        },
        {
          "name": "symbol_position",
          "comment": "符号位置（before/after）",
          "constraint": ""
        },
        {
          "name": "priority",
          "comment": "优先级",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态",
          "constraint": ""
        }
      ],
      "note": "一个 Market 支持多种货币，is_default 标记默认货币"
    },
    {
