      "comment": "翻译内容",
      "columns": [
        {
          "name": "translation_id",
          "comment": "翻译ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "resource_type",
          "comment": "资源类型（product/category/cms）",
          "constraint": ""
        },
        {
          "name": "resource_id",
          "comment": "资源ID",
          "constraint": ""
        },
        {
          "name": "field_name",
          "comment": "字段名",
          "constraint": ""
        },
        {
          "name": "language_code",
          "comment": "目标语言",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "translated_value",
          "comment": "翻译内容",
          "constraint": ""
        },
        {
          "name": "translation_source",
          "comment": "翻译来源（manual/ai/vendor）",
          "constraint": ""
        },
        {
          "name": "source_version",
          "comment": "源内容版本号",
          "constraint": ""
        },
        {
          "name": "source_hash",
          "comment": "源内容哈希",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态（draft/pending_review/approved/outdated）",
          "constraint": ""
        },
        {
          "name": "reviewed_by",
          "comment": "审核人",
          "constraint": ""
        },
        {
          "name": "reviewed_at",
          "comment": "审核时间",
          "constraint": ""
        }
      ],
      "note": "混合策略：核心内容集中翻译，长尾内容分布式翻译"
    }
  ],
  "relations": [
    {
      "from": "country",
      "to": "currency",
      "type": "N:1",
      "label": "法定货币",
      "color": "#4A90D9",
      "penwidth": 1.4
    },
    {
      "from": "country",
      "to": "language",
