      "penwidth": 1.4
    },
    {
      "from": "market_country",
      "to": "country",
      "type": "N:1",
      "label": "国家",
      "color": "#E8833A"
    },
    {
      "from": "market_country",
      "to": "timezone",
      "type": "N:1",
      "label": "本地时区",
      "color": "#90A4AE",
      "style": "dashed"
    },
    {
      "from": "market_language",
      "to": "market",
      "type": "N:1",
      "label": "市场",
      "color": "#E8833A"
    },
    {
      "from": "market_language",
      "to": "language",
      "type": "N:1",
      "label": "语言",
      "color": "#E8833A"
    },
    {
      "from": "market_currency",
      "to": "market",
      "type": "N:1",
      "label": "市场",
      "color": "#E8833A"
    },
    {
      "from": "market_currency",
      "to": "currency",
      "type": "N:1",
      "label": "货币",
      "color": "#E8833A"
    },
    {
      "from": "translation",
      "to": "language",
      "type": "N:1",
      "label": "目标语言",
      "color": "#7B1FA2",
      "penwidth": 1.4
    }
  ],
  "design_rules": {
    "market_definition": "Market = 商业运营单元（销售区域），一个Market可包含多个国家（如EU Market包含FR/DE/IT/ES），也可只含一个国家（如US Market）",
    "market_country_unique": "market_country 表的 (market_id, country_id) 组合唯一，确保一个国家只能归属一个Market",
    "country_simplicity": "country 表只保留基础属性（名称、大洲、时区、电话区号、默认货币/语言），税费/合规/地址等业务配置由独立模块管理",
    "translation_strategy": "混合策略：核心内容（商品/类目）集中翻译，长尾内容（UGC）分布式翻译。source_hash 检测源内容变化，status=outdated 触发重译",
    "channel_granularity": "Channel 归属 Market，按策略划分（如 EU Market 的 Online/Retail 渠道），不按国家拆分",
    "cross_border_default": "Market 内跨境购买是默认能力（cross_border_enabled=true），无需额外配置",
    "domain_strategy": "域名策略：默认使用 market_country.use_independent_domain=true 启用独立域名（如 looply.fr），否则跟随 Market 统一域名。支持渐进式策略：初期全用统一域名，业务成熟后按国家切换独立域名",
    "exception_config": "market_country.custom_config 存储国家级例外配置（JSON），覆盖 Market 默认策略",
    "reference_data_pk": "基础参考数据（country/currency/language）使用国际标准代码作主键（ISO 3166-1/ISO 4217/ISO 639-1），语义清晰，跨模块引用时可读性强",
    "timezone_design": "时区独立为 timezone 实体（IANA 标识作主键），通过 country_timezone 关联表支持一国多时区（如US有4个时区）。Market 有基准时区（base_timezone），market_country 可选覆盖本地时区（local_timezone）",
    "business_day_cutoff": "Market 级别设置业务日切时间（business_day_cutoff），影响报表统计和库存快照。market_country 可选覆盖本地日切时间（local_day_cutoff）",
    "audit_fields": "所有实体统一通过数据库层自动维护审计字段（created_by/created_at/updated_by/updated_at），不在 ER 图中逐表重复列出"
  }
}
